{"content":[{"type":"text","text":"import { useState } from "react";
import { createRoot } from "react-dom/client";

import {
  Button,
  CommandFeedback,
  EvidenceBlock,
  LanguageSegmentedControl,
  StateSummary,
  TextInput,
  type UiLocale,
} from "../src";
import "../src/styles.css";

function UiFoundationFixture() {
  const [locale, setLocale] = useState<UiLocale>("en-US");

  return (
    <main aria-label="UI foundation fixture">
      <h1>UI foundation fixture</h1>
      <LanguageSegmentedControl value={locale} onChange={setLocale} />
      <p>Selected locale: {locale}</p>
      <Button isLoading>Save evidence</Button>
      <Button variant="quiet">Quiet action</Button>
      <TextInput label="Project name" error="Choose a project name." defaultValue="Incomplete" />
      <CommandFeedback commandId="command-42" labels={{ commandId: "Command ID", latestRevision: "Latest revision", subjectId: "Subject ID" }} latestRevision="revision-7" reason="The command was accepted." recoveryAction="Observe the result." status="accepted" subjectId="workflow-42" title="Command accepted" />
      <StateSummary ariaLabel="State summary" state="ReviewRejected" reason="Evidence is incomplete." nextStepLabel="Next action" nextStep="Attach provenance." />
      <EvidenceBlock ariaLabel="Evidence" subjectId="gate-42" digest="sha256:abc123" labels={{ digest: "Digest", provenance: "Provenance", result: "Result", source: "Source", subjectId: "Subject ID" }} result="Pass" provenance="Verifier run 19" source="Gate verifier" />
    </main>
  );
}

createRoot(document.getElementById("root")!).render(<UiFoundationFixture />);
import { expect, test } from "@playwright/test";

test("ui-foundation exposes accessible language, state, command, and evidence surfaces", async ({ page }) => {
  await page.goto("/");

  await expect(page.getByRole("main", { name: "UI foundation fixture" })).toBeVisible();
  await expect(page.getByRole("button", { name: "Save evidence" })).toBeDisabled();
  await expect(page.getByText("Command accepted")).toBeVisible();
  await expect(page.getByText("ReviewRejected")).toBeVisible();
  await expect(page.getByText("sha256:abc123")).toBeVisible();

  const chinese = page.getByRole("radio", { name: "中文" });
  await chinese.focus();
  await page.keyboard.press("Enter");

  await expect(page.getByText("Selected locale: zh-CN")).toBeVisible();
  await expect(chinese).toHaveAttribute("aria-checked", "true");
});

test("ui-foundation primitives expose hover, pressed, loading, and invalid visual states", async ({ page }) => {
  await page.goto("/");

  const loadingButton = page.getByRole("button", { name: "Save evidence" });
  await expect(loadingButton).toHaveCSS("opacity", "0.75");
  await expect(loadingButton).toHaveAttribute("aria-busy", "true");
  await expect(loadingButton).toContainText("Save evidence");

  const quietButton = page.getByRole("button", { name: "Quiet action" });
  await quietButton.hover();
  await expect(quietButton).toHaveCSS("background-color", "rgb(232, 242, 255)");
  await page.mouse.down();
  await expect(quietButton).toHaveCSS("transform", "matrix(0.97, 0, 0, 0.97, 0, 0)");
  await page.mouse.up();

  const invalidInput = page.getByRole("textbox", { name: "Project name" });
  await expect(invalidInput).toHaveAttribute("aria-invalid", "true");
  await expect(invalidInput).toHaveCSS("border-color", "rgb(180, 35, 43)");

  await invalidInput.focus();
  await expect(invalidInput).toHaveCSS("outline-color", "rgb(0, 110, 219)");
});
"}]}

