  function channel(value: string) {
    const c = value.match(/\d+/g)?.map(Number) ?? [];
    return c.map((part) => {
      const normalized = part / 255;
      return normalized <= 0.03928 ? normalized / 12.92 : ((normalized + 0.055) / 1.055) ** 2.4;
    });
  }
  const luminance = (value: string) => {
    const [r, g, b] = channel(value);
    return 0.2126 * r + 0.7152 * g + 0.0722 * b;
  };
  const background = luminance(getComputedStyle(document.querySelector("button")!).backgroundColor);
  const foreground = luminance(getComputedStyle(document.querySelector("button")!).color);
  return (Math.max(background, foreground) + 0.05) / (Math.min(background, foreground) + 0.05);
})).toBeGreaterThanOrEqual(4.5);

